config.solution:
# Comandos CLI:

# 1. GitHub (HTTP, project scope)
claude mcp add --scope project --transport http github https://api.githubcopilot.com/mcp/

# 2. Filesystem (Stdio, local scope - default)
claude mcp add --transport stdio filesystem -- npx -y @modelcontextprotocol/server-filesystem ~/Documents

# 3. PostgreSQL (Stdio, project scope, con env var)
claude mcp add --scope project --transport stdio postgres --env DB_URL="${DATABASE_URL}" -- npx -y @bytebase/dbhub

# Archivo .mcp.json:
{
  "mcpServers": {
    "github": {
      "type": "http",
      "url": "https://api.githubcopilot.com/mcp/",
      "headers": {
        "Authorization": "Bearer ${GITHUB_TOKEN}"
      }
    },
    "postgres": {
      "type": "stdio",
      "command": "npx",
      "args": ["-y", "@bytebase/dbhub"],
      "env": {
        "DB_URL": "${DATABASE_URL:-postgresql://localhost/default}"
      }
    }
  }
}
